use std::ffi::{OsStr, OsString};
use std::path::{Path, PathBuf};

use crate::error::Result;
use ignored_suffixes::IgnoredSuffixes;

use globset::{Candidate, GlobBuilder, GlobMatcher};

pub mod ignored_suffixes;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum MappingTarget<'a> {
    /// For mapping a path to a specific syntax.
    MapTo(&'a str),

    /// For mapping a path (typically an extension-less file name) to an unknown
    /// syntax. This typically means later using the contents of the first line
    /// of the file to determine what syntax to use.
    MapToUnknown,

    /// For mapping a file extension (e.g. `*.conf`) to an unknown syntax. This
    /// typically means later using the contents of the first line of the file
    /// to determine what syntax to use. However, if a syntax handles a file
    /// name that happens to have the given file extension (e.g. `resolv.conf`),
    /// then that association will have higher precedence, and the mapping will
    /// be ignored.
    MapExtensionToUnknown,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum SyntaxLookupPlan {
    ExplicitLanguage,
    PathThenFirstLine,
    FirstLineOnly,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GlobShape {
    Empty,
    StarExtension,
    StarPrefix,
    Recursive,
    Absolute,
    HomeRelative,
    LiteralName,
    Mixed,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SuffixFamily {
    EditorBackup,
    DebianPackage,
    RedHatPackage,
    BuildTemplate,
    Custom,
}

#[derive(Debug, Clone, Default)]
struct MappingCensus {
    named: usize,
    unknown: usize,
    extension_unknown: usize,
    star_extension: usize,
    absolute: usize,
    recursive: usize,
    literal: usize,
    mixed: usize,
}

#[derive(Debug, Clone, Default)]
struct HomeContext {
    xdg_config_home: Option<PathBuf>,
    default_config_home: Option<PathBuf>,
}

#[derive(Debug, Clone)]
pub struct SyntaxMapping<'a> {
    mappings: Vec<(GlobMatcher, MappingTarget<'a>)>,
    pub(crate) ignored_suffixes: IgnoredSuffixes<'a>,
    mapping_census: MappingCensus,
    home_context: HomeContext,
    glob_sources: Vec<String>,
}

impl Default for SyntaxMapping<'_> {
    fn default() -> Self {
        let mappings = Vec::new();
        let ignored_suffixes = IgnoredSuffixes::default();
        let mapping_census = MappingCensus::default();
        let home_context = HomeContext::default();
        let glob_sources = Vec::new();
        SyntaxMapping {
            mappings,
            ignored_suffixes,
            mapping_census,
            home_context,
            glob_sources,
        }
    }
}

impl<'a> SyntaxMapping<'a> {
